"""Autorskie reguły i dokładne kotwice do odczytanych źródeł; bez konwersji runtime."""

def sy(section, pages):
    return [('SEN', f'{section}; fizyczne strony PDF {pages}'), ('SPL', f'{section}; fizyczne strony PDF {pages}')]

def gl(entries, pages):
    return [('GPL', f'Hasła {entries}; fizyczne strony PDF {pages}')]

def hb(section, pages):
    return [('HEN', f'{section}; fizyczne strony PDF {pages}')]

